import { BadgeCheckIcon, CodeIcon } from '@heroicons/react/solid';
import React, { useEffect } from 'react';
import { skills } from '../data';
import AOS from 'aos';
import 'aos/dist/aos.css';

export default function Skills() {
    useEffect(() => {
        AOS.init({ duration: 1500 });
    }, []);
    return (
        <div className="transform scale-90">
            <section id="skills" data-aos-offset="550" data-aos="fade-up" data-aos-once="true">
                <div className="container px-5 py-10 mx-auto">
                    <div className="text-center mb-20">
                        <CodeIcon className="w-10 inline-block mb-4" />
                        <h1 className="sm:text-4xl text-3xl font-medium title-font text-white mb-4">Skills &amp; Technologies</h1>
                        <p className="text-base leading-relaxed xl:w-2/4 lg:w-3/4 mx-auto"></p>
                    </div>
                    <div className="flex flex-wrap lg:w-4/5 sm:mx-auto sm:mb-2 -mx-2">
                        {skills.map((skill, index) => (
                            <div
                                key={skill}
                                className={`p-2 sm:w-1/2 w-full ${index % 2 === 0 ? 'aos-right' : 'aos-left'}`}
                                data-aos={index % 2 === 0 ? 'fade-right' : 'fade-left'}
                                data-aos-delay={Math.floor(index / 2) * 200}
                                data-aos-once="true"
                            >
                                <div className="bg-gray-800 rounded flex p-4 h-full items-center">
                                    <BadgeCheckIcon className="text-green-400 w-6 h-6 flex-shrink-0 mr-4" />
                                    <span className="title-font font-medium text-white">{skill}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </div>
    );
}



